/**
 * Problem bank for the seed script.
 *
 * Every problem reads from STDIN and prints to STDOUT (this is what Judge0 expects).
 * Expected outputs are generated by the reference solution `ref`, so test cases
 * can never disagree with the statement. The first two inputs are SAMPLE
 * (visible) cases; the rest are HIDDEN.
 */

export type Kind = "int" | "two" | "three" | "arr" | "arrT" | "str";

export type SeedProblem = {
  title: string;
  world: 1 | 2 | 3;
  topic: string;
  difficulty: "EASY" | "MEDIUM" | "HARD";
  kind: Kind;
  description: string;
  inputFormat: string;
  outputFormat: string;
  constraints: string;
  explanation: string;
  tests: string[];
  ref: (input: string) => string;
  daily?: boolean;
};

const nums = (s: string) => s.trim().split(/\s+/).map(Number);
const lines = (s: string) => s.replace(/\r/g, "").split("\n");
const arrOf = (s: string) => nums(lines(s)[1]);
const yn = (b: boolean) => (b ? "Yes" : "No");

const gcd = (a: number, b: number): number => (b === 0 ? a : gcd(b, a % b));

