/* ---------- starter code per input kind ---------- */

export function starterFor(kind: Kind) {
  const py: Record<Kind, string> = {
    int: "n = int(input())\n\n# write your code here\n",
    two: "a, b = map(int, input().split())\n\n# write your code here\n",
    three: "a, b, c = map(int, input().split())\n\n# write your code here\n",
    arr: "n = int(input())\narr = list(map(int, input().split()))\n\n# write your code here\n",
    arrT: "n = int(input())\narr = list(map(int, input().split()))\ntarget = int(input())\n\n# write your code here\n",
    str: "s = input().strip()\n\n# write your code here\n",
  };
  const cppRead: Record<Kind, string> = {
    int: "    long long n; cin >> n;",
    two: "    long long a, b; cin >> a >> b;",
    three: "    long long a, b, c; cin >> a >> b >> c;",
    arr: "    int n; cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;",
    arrT: "    int n; cin >> n;\n    vector<long long> arr(n);\n    for (auto &x : arr) cin >> x;\n    long long target; cin >> target;",
    str: "    string s; getline(cin, s);",
  };
  const javaRead: Record<Kind, string> = {
    int: "        long n = sc.nextLong();",
    two: "        long a = sc.nextLong(), b = sc.nextLong();",
    three: "        long a = sc.nextLong(), b = sc.nextLong(), c = sc.nextLong();",
    arr: "        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();",
    arrT: "        int n = sc.nextInt();\n        long[] arr = new long[n];\n        for (int i = 0; i < n; i++) arr[i] = sc.nextLong();\n        long target = sc.nextLong();",
    str: "        sc.nextLine();\n        String s = sc.nextLine().trim();",
  };
  // For string problems Java: we don't want to skip a line. Fix below.
  const javaStr = "        String s = sc.nextLine().trim();";
  return {
    python: py[kind],
    cpp: `#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n${cppRead[kind]}\n\n    // write your code here\n\n    return 0;\n}\n`,
    java: `import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n${
      kind === "str" ? javaStr : javaRead[kind]
    }\n\n        // write your code here\n    }\n}\n`,
  };
}
